const assert=require('node:assert/strict'),fs=require('node:fs/promises'),root=require('node:path').resolve(__dirname,'..');
const {chromium}=require(root+'/tools/node_modules/playwright'),{startHtmlServer}=require(root+'/tools/lib/ui-server.cjs');
(async()=>{const out='/tmp/feedback-camp-ui';await fs.mkdir(out,{recursive:true});const file=out+'/working.html';await fs.writeFile(file,require(root+'/tools/build.cjs').build({root,write:false}).html);const server=await startHtmlServer(file);let b;const results=[];
try{b=await chromium.launch({executablePath:process.env.CHROMIUM_EXECUTABLE_PATH||'/usr/bin/chromium'});for(const width of [1366,390,768]){const ctx=await b.newContext({viewport:{width,height:width===1366?768:900},isMobile:width<1000,hasTouch:width<1000});const p=await ctx.newPage();p.setDefaultTimeout(8000);await p.route('https://fonts.googleapis.com/**',r=>r.fulfill({body:'',contentType:'text/css'}));const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(server.url);await p.evaluate(()=>{DEMO.on=false;newGame(6);G.tut={done:true,step:99};UI.title=false;UI.tab='staff';UI.sub={staff:'sc'};const P=sprcPlan(G.user);P.s1='gu';P.s2='home';P.pgN=2;A.goWork('스프링캠프');render();});const b12=p.locator('[data-a=sprcPg][data-v="12:"]'),b2=p.locator('[data-a=sprcPg][data-v="2:"]');assert.equal(await b12.isDisabled(),true);assert.equal(await b2.isDisabled(),false);await b2.click();assert.equal(await p.evaluate(()=>sprcPlan(G.user).pgN),2);await p.evaluate(()=>{const cid=OCL.find(c=>c.s[0]===1&&c.s[1]==='az').id;sisInit().p[cid]={tid:G.user,y:G.year};for(const [i,t]of G.teams.filter(t=>t.id!==G.user).entries())if(i<3)sprcPlan(t.id).s1='az';A.goWork('스프링캠프');render();});const az=p.locator('[data-a=sprcBook][data-v="1:az"]');assert.equal(await az.isDisabled(),false);assert.match(await az.innerText(),/자매구단 우선 예약/);assert.ok(!(await p.locator('main').innerText()).includes('-1자리'));await p.screenshot({path:out+'/'+width+'.png',fullPage:true});assert.deepEqual(errors,[]);results.push({width,max12Disabled:true,cap2Enabled:true,cap2Action:true,priorityEnabled:true,noNegativeSeats:true,errors});await ctx.close();}await fs.writeFile(out+'/results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await b?.close();await server.close();}})().catch(e=>{console.error(e.stack);process.exitCode=1;});
